import{_ as e,o,c as d,a2 as a}from"./chunks/framework.CQxpk36T.js";const u=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"en/depannage.md","filePath":"en/depannage.md","lastUpdated":1793574169000}'),r={name:"en/depannage.md"};function n(s,t,i,h,c,l){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="messages-on-load" tabindex="-1">Messages on load <a class="header-anchor" href="#messages-on-load" aria-label="Permalink to &quot;Messages on load&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>What to do</th></tr></thead><tbody><tr><td><code>Propriété introuvable : …/index.ts</code> (property not found)</td><td><code>PROPRIETE</code> in <code>.env.local</code> doesn&#39;t match any folder in <code>proprietes/</code></td></tr><tr><td><code>Bâtiment … absent de site.json</code> (building missing)</td><td>A section refers to an id that isn&#39;t in <code>site.json</code> (see <code>plan.svg</code>, or <code>terrain.json</code>)</td></tr><tr><td><code>cadastre.json introuvable</code></td><td>The IGN tools expect <code>proprietes/&lt;name&gt;/cadastre.json</code> (<a href="/HAven-docs/en/guide/terrain">The land</a>)</td></tr></tbody></table><p>Run <code>npm test</code>: it checks every folder in <code>proprietes/</code> and says exactly what&#39;s wrong (duplicate ids, a car without a spot, a plan room outside the walls…).</p><h2 id="the-model" tabindex="-1">The model <a class="header-anchor" href="#the-model" aria-label="Permalink to &quot;The model&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>What to do</th></tr></thead><tbody><tr><td>A roof goes through the neighbour&#39;s</td><td>Correct <code>eave</code> / <code>ridge</code>, or use <code>into</code> / <code>against</code> (<a href="/HAven-docs/en/guide/batiments#roofs">Roofs</a>)</td></tr><tr><td>Two buildings overlap at an angle</td><td>Check the <a href="/HAven-docs/en/guide/batiments#skewed-gables">skewed gables</a>, or set <code>skew</code> by hand</td></tr><tr><td>A window appears behind an attached building</td><td>Automatic windows avoid attached walls; a window placed by hand doesn&#39;t</td></tr><tr><td>A window&#39;s shutters stay closed</td><td>Remove <code>closed: true</code> from the window in <code>facade.windows</code></td></tr><tr><td>A building moved in the editor left its parking spot behind</td><td>Spots, yards and runs don&#39;t follow: update their coordinates</td></tr><tr><td>The sun is in the wrong place</td><td>Check <code>origine</code> (latitude, longitude) in <code>terrain.json</code> or <code>cadastre.json</code>, and the device&#39;s clock</td></tr><tr><td>Stutters on an old phone</td><td>Settings → Qualité graphique → <strong>Économe</strong></td></tr><tr><td>Black screen, &quot;WebGL&quot;</td><td>The browser or graphics card lacks WebGL 2: update the browser</td></tr></tbody></table><h2 id="home-assistant" tabindex="-1">Home Assistant <a class="header-anchor" href="#home-assistant" aria-label="Permalink to &quot;Home Assistant&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>What to do</th></tr></thead><tbody><tr><td>&quot;Se connecter&quot; does nothing, or a network error</td><td>The address must be reachable <strong>from the device</strong> (not just from the server); try it in the browser first</td></tr><tr><td>Connecting fails from an HTTPS page</td><td>Home Assistant must be on HTTPS too (<a href="/HAven-docs/en/home-assistant/#http-or-https">HTTP or HTTPS</a>)</td></tr><tr><td>A lamp doesn&#39;t appear</td><td>It must be assigned to an <strong>Area</strong>, and that Area linked to a room (<code>area</code>)</td></tr><tr><td>A room&#39;s windows don&#39;t light up</td><td>Check that the room&#39;s <code>area</code> is the Area id, not its name</td></tr><tr><td>An &quot;Effect&quot;, &quot;Update&quot;… entity clutters the panel</td><td>They are left out if Home Assistant classifies them as configuration or diagnostic; otherwise hide them in HA</td></tr><tr><td>The car stays away</td><td>The <code>location</code> entity&#39;s state must be a spot id, or <code>on</code> / <code>home</code></td></tr><tr><td>A tap seems to do nothing</td><td>The device pulses until it answers; if it goes back to its state, Home Assistant refused the command (device unreachable)</td></tr></tbody></table><h2 id="hosting" tabindex="-1">Hosting <a class="header-anchor" href="#hosting" aria-label="Permalink to &quot;Hosting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>What to do</th></tr></thead><tbody><tr><td>Nothing loads on <code>http://&lt;ip&gt;:8099</code></td><td>Normal: the container only listens on the machine itself. Go through Tailscale or a proxy</td></tr><tr><td>Changes don&#39;t show</td><td>Run <code>npm run deploy</code> again; on the phone, close and reopen the app</td></tr><tr><td>The app doesn&#39;t open offline</td><td>It needs HTTPS (<a href="/HAven-docs/en/hebergement#https">HTTPS</a>)</td></tr><tr><td>The editor&#39;s Enregistrer button became Télécharger</td><td>Normal on a server: drop the file into the property folder, then <code>npm run deploy</code></td></tr></tbody></table>',10)])])}const m=e(r,[["render",n]]);export{u as __pageData,m as default};
